# PATCH_V6_ATOMIC_RISK_LEDGER_BEGIN
try{

$ledger="C:\alpaca-bot\ORG_BOT_UNIFIED\runtime\paper\state\risk_ledger_atomic.json"
$dir=Split-Path $ledger
New-Item -ItemType Directory -Force $dir|Out-Null

$run_id=[guid]::NewGuid().ToString()

if(!(Test-Path $ledger)){
    $init=[ordered]@{
        kind="atomic_risk_ledger_v6"
        created_ts=(Get-Date).ToString("s")
        pid=$PID
        run_id=$run_id
        profile=$env:TBOT_PROFILE
    }
    $tmp="$ledger.tmp"
    ($init|ConvertTo-Json -Compress)|Set-Content $tmp -Encoding UTF8
    Move-Item $tmp $ledger -Force
}else{
    $existing=Get-Content $ledger -Raw | ConvertFrom-Json
    if($existing.pid -and ($existing.pid -ne $PID)){
        Write-Host "Atomic ledger already owned by PID=$($existing.pid)"
    }
}

}catch{
Write-Host "Atomic ledger guard failure"
}
# PATCH_V6_ATOMIC_RISK_LEDGER_END
